export const source = "import HR_DIRECT_REPORTS:DirectReports;\n\nDeclare Function GetText PeopleCode FUNCLIB_HR_DR.HR_DR_TEXT_FN FieldFormula;\nDeclare Function GetSimpleText PeopleCode FUNCLIB_HR_DR.HR_DR_TEXT_FN FieldFormula;\nDeclare Function InitializeTarget PeopleCode FUNCLIB_HR_DR.HR_DR_INIT_FN FieldFormula;\nDeclare Function IsJobSelected PeopleCode FUNCLIB_HR_DR.HR_DR_UTIL_FN FieldFormula;\nDeclare Function GetSelectedManager PeopleCode FUNCLIB_HR_DR.HR_DR_UTIL_FN FieldFormula;\nDeclare Function SetRoot PeopleCode FUNCLIB_HR_DR.HR_DR_UTIL_FN FieldFormula;\nDeclare Function DrillDown PeopleCode FUNCLIB_HR_DR.HR_DR_UTIL_FN FieldFormula;\nDeclare Function TransferToMessage PeopleCode FUNCLIB_HR_DR.HR_DR_UTIL_FN FieldFormula;\nDeclare Function InitPage4Text PeopleCode FUNCLIB_HR_DR.HR_DR_TEXT_FN FieldFormula;\n\n/* Following globals are available to the UI class to denote that the */\n/* user is acting as a proxy for another person.                      */\nGlobal string &GBL_ProxyForEmplid;\nGlobal string &GBL_ProxyForOprid;\nGlobal number &GBL_ProxyForERN;\n\nComponent HR_DIRECT_REPORTS:DirectReports &DirectReports;\nComponent string &ReturnPage, &EffectiveManagerName, &UserName;\nComponent string &DelegateForEmplid, &DelegateForPosition;\nComponent number &DelegateForERN;\nComponent boolean &IsProxy;\n\nLocal Rowset &RS_DelegateVW;\nLocal number &i, &SelectedManagerRowNbr;\nLocal string &PositionNbr;\nLocal boolean &ManagerSelected;\nLocal boolean &ValidData;\n\n\nFunction ResetMyEEFlag()\n   \n   &RS_DelegateVW = GetLevel0()(1).GetRowset(Scroll.HCDL_MYDLGTOR);\n   If &RS_DelegateVW.ActiveRowCount = 1 Then\n      /* No managers have delegated to this user */\n      DERIVED_HR_DR.HR_DR_MY_EE_FLG = \"Y\";\n   Else\n      /* At least one manager has delegated authority to this user. */\n      DERIVED_HR_DR.HR_DR_MY_EE_FLG = \"N\";\n      For &i = 1 To &RS_DelegateVW.ActiveRowCount\n         If &RS_DelegateVW(&i).Selected = True Then\n            /* The \"process my own EEs\" row has a blank Emplid and Position. */\n            If None(&RS_DelegateVW(&i).HCDL_MYDLGTOR.DELEGATOR_ID.Value) Then\n               DERIVED_HR_DR.HR_DR_MY_EE_FLG = \"Y\";\n            End-If;\n            Break;\n         End-If;\n      End-For;\n   End-If;\n   \nEnd-Function;\n\n\nFunction ResetUserName(&SelectedManagerRowNbr As number)\n   \n   /* Reset the \"Name\" field of the Page Headings to reflect that the User is */\n   /* \"standing in\" for another manager.                                      */\n   &IsProxy = False;\n   &EffectiveManagerName = &UserName;\n   DERIVED_HR_DR.HR_DR_USERNAME = &UserName;\n   If DERIVED_HR_DR.HR_DR_MY_EE_FLG <> \"Y\" Then\n      &IsProxy = True;\n      If All(&SelectedManagerRowNbr) Then\n         &RS_DelegateVW = GetRowset(Scroll.HCDL_MYDLGTOR);\n         If All(&RS_DelegateVW(&SelectedManagerRowNbr).HCDL_MYDLGTOR.DELEGATOR_ID.Value) Then\n            &EffectiveManagerName = &RS_DelegateVW(&SelectedManagerRowNbr).HCDL_MYDLGTOR.NAME_DISPLAY.Value;\n         End-If;\n         /*\n         <UserName> (proxy for <EffectiveManagerName>)\n         */\n         DERIVED_HR_DR.HR_DR_USERNAME = GetText(\"PROXY_FOR_TITLE\", &UserName, &EffectiveManagerName, \" \", \" \", \" \");\n      End-If;\n   End-If;\nEnd-Function;\n\nFunction ValidateData\n   Local string &MessageText;\n   &ValidData = False;\n   If None(DERIVED_HR_DR.ASOFDATE) Then\n      /* \n        \"You must enter a 'Transaction Effective Date'. \n        This date determines the effective date of the Location Change.\"\n      */\n      rem TransferToMessage(\"E\", GetSimpleText(\"MSG_EFFDT_ERROR\"), %Page);\n      Error (GetSimpleText(\"MSG_EFFDT_ERROR\"));\n   End-If;\n   \n   If DERIVED_HR_DR.HR_DR_MY_EE_FLG = \"Y\" Then\n      /* \n        The user IS processing their own employees. \n        If the user holds multiple concurrent active jobs, \n        they must select one of these jobs before continuing.                                  */\n      If IsJobSelected() Then\n         &ValidData = True;\n      Else\n         /* \n            \"Since you hold multiple positions and you'll be processing \n             your own employees, you must first select a position to \n             work with.\" \n         */\n         rem TransferToMessage(\"E\", GetSimpleText(\"MSG_MJ_ERROR\"), %Page);\n         Error (GetSimpleText(\"MSG_MJ_ERROR\"));\n      End-If;\n   Else\n      /* \n        The user is NOT processing their own employees. \n        They must select a manager from the list of managers that have \n        authorized this user to process their employees.                     */\n      &SelectedManagerRowNbr = GetSelectedManager();\n      If All(&SelectedManagerRowNbr) Then\n         &ValidData = True;\n      Else\n         /*\n         \"If you want to process transactions for your own employees, \n         you must indicate this by checking the I Want to process \n         my own employees box. \n         If you want to process transactions for another manager, \n         you must first select a manager from the list of managers that \n         have delegated authority to you.\"\n         */\n         rem TransferToMessage(\"E\", GetSimpleText(\"MSG_MJ_DLGT1\"), %Page);\n         Error (GetSimpleText(\"MSG_MJ_DLGT1\"));\n      End-If;\n      \n   End-If;\nEnd-Function;\n\n&GBL_ProxyForEmplid = \"\";\n&GBL_ProxyForOprid = \"\";\n&GBL_ProxyForERN = 0;\n\nResetMyEEFlag();\nValidateData();\nIf &ValidData Then\n   SetRoot();\n   \n   ResetUserName(&SelectedManagerRowNbr);\n   /* Re-init Page 4 (Group Id) page to reflect Group Manager name. */\n   InitPage4Text();\n   If &DirectReports.NavigationMethod <> 7 Then\n      /* Initialize the API Target Emplid/ERN */\n      InitializeTarget();\n      /* Set the API \"AsOfDate\" */\n      &DirectReports.AsOfDate = DERIVED_HR_DR.ASOFDATE;\n      /* Set the \"Delegate For\" component variables. */\n      &DelegateForEmplid = &DirectReports.TargetEmplid;\n      &DelegateForERN = &DirectReports.TargetERN;\n      &DelegateForPosition = &DirectReports.TargetPosition;\n      \n      /* Set the Global variables, which will be passed back       */\n      /* to the calling application as UI Class Properties.        */\n      &GBL_ProxyForEmplid = &DirectReports.TargetEmplid;\n      &GBL_ProxyForOprid = &DirectReports.TargetOprid;\n      &GBL_ProxyForERN = &DirectReports.TargetERN;\n      \n      /*     If All(&DelegateForEmplid) And\n            &DirectReports.TargetEmplid <> %EmployeeId Then\n         &GBL_ProxyForEmplid = &DirectReports.TargetEmplid;\n         &GBL_ProxyForERN = &DirectReports.TargetERN;\n      End-If;\n */\n      /* Invoke the data service to deliver the initial direct reports */\n      DrillDown(&DirectReports.TargetEmplid, &DirectReports.TargetERN, &DirectReports.TargetPosition);\n      /* Transfer to the Select Employees Page */\n      TransferPage(Page.HR_DR_SELECT_EMPS);\n   Else\n      /* \n        Navigation Method is \"Group Id\".\n        Ask the user for the Group Id to use. \n      */\n      TransferPage(Page.HR_DR_SELECT_GROUP);\n   End-If;\nEnd-If;\n";
